@_mutmut_mutated(mutants_x_place_notional_order__mutmut)
async def place_notional_order(
    api_key: str,
    api_secret: str,
    symbol: str,
    notional: float,
    side: str,
    time_in_force: str = "day",
    live: bool = False,
    entry_price: float | None = None,
) -> dict:
    price = entry_price
    if price is None or price <= 0:
        conid = await search_conid(symbol, api_key)
        base_url = _base()
        async with shared_session() as s:
            async with s.get(
                f"{base_url}/iserver/marketdata/snapshot",
                headers=_headers(api_key),
                params={"conids": str(conid), "fields": "31"},
                ssl=_ssl_ctx(),
            ) as r:
                if r.status == 200:
                    data = await r.json()
                    if isinstance(data, list) and data:
                        price_str = data[0].get("31") or data[0].get("last")
                        if price_str:
                            price = float(price_str)
        if price is None or price <= 0:
            raise ValueError(f"Could not determine price for symbol {symbol} to calculate notional quantity")

    qty = round(notional / price, 4)
    if qty <= 0:
        qty = 1.0

    return await place_order(
        api_key=api_key,
        api_secret=api_secret,
        symbol=symbol,
        qty=qty,
        side=side,
        order_type="market",
        time_in_force=time_in_force,
        live=live,
    )


