@_mutmut_mutated(mutants_x_submit_bracket_stop_order__mutmut)
async def submit_bracket_stop_order(
    api_key: str,
    api_secret: str,
    symbol: str,
    notional: float,
    side: str,
    stop_price: float,
    take_profit_price: float | None = None,
    entry_price: float | None = None,
    live: bool = False,
) -> dict:
    base_url = _base()
    acct = await get_account(api_key, api_secret, live)
    acct_id = acct["id"]
    conid = await search_conid(symbol, api_key)

    price = entry_price
    if price is None or price <= 0:
        async with shared_session() as s:
            async with s.get(
                f"{base_url}/iserver/marketdata/snapshot",
                headers=_headers(api_key),
                params={"conids": str(conid), "fields": "31"},
                ssl=_ssl_ctx(),
            ) as r:
                if r.status == 200:
                    data = await r.json()
                    if isinstance(data, list) and data:
                        price_str = data[0].get("31") or data[0].get("last")
                        if price_str:
                            price = float(price_str)

    if price is None or price <= 0:
        raise ValueError(f"Could not determine price for symbol {symbol} to calculate notional quantity")

    qty = round(notional / price, 4)
    if qty <= 0:
        qty = 1.0

    parent_id = f"parent_{uuid.uuid4().hex[:8]}"
    tp_id = f"tp_{uuid.uuid4().hex[:8]}"
    sl_id = f"sl_{uuid.uuid4().hex[:8]}"

    orders = []

    # Parent Order
    parent_order = {
        "acctId": acct_id,
        "conid": conid,
        "secType": "STK",
        "cOID": parent_id,
        "orderType": "MKT",
        "side": side.upper(),
        "quantity": float(qty),
        "tif": "DAY",
    }
    orders.append(parent_order)

    # Child Order: Stop Loss
    child_side = "SELL" if side.upper() == "BUY" else "BUY"
    stop_order = {
        "acctId": acct_id,
        "conid": conid,
        "parentId": parent_id,
        "cOID": sl_id,
        "orderType": "STP",
        "side": child_side,
        "quantity": float(qty),
        "auxPrice": float(stop_price),
        "tif": "GTC",
    }
    orders.append(stop_order)

    # Child Order: Take Profit (optional)
    if take_profit_price is not None:
        tp_order = {
            "acctId": acct_id,
            "conid": conid,
            "parentId": parent_id,
            "cOID": tp_id,
            "orderType": "LMT",
            "side": child_side,
            "quantity": float(qty),
            "price": float(take_profit_price),
            "tif": "GTC",
        }
        orders.append(tp_order)

    async with shared_session() as s:
        async with s.post(
            f"{base_url}/iserver/account/{acct_id}/orders",
            headers=_headers(api_key),
            json={"orders": orders},
            ssl=_ssl_ctx(),
        ) as r:
            r.raise_for_status()
            res = await r.json()
            if isinstance(res, list) and len(res) > 0:
                first = res[0]
                if "replyId" in first:
                    reply_id = first["replyId"]
                    async with s.post(
                        f"{base_url}/iserver/reply/{reply_id}",
                        headers=_headers(api_key),
                        json={"confirmed": True},
                        ssl=_ssl_ctx(),
                    ) as reply_r:
                        reply_res = await reply_r.json()
                        return reply_res[0] if isinstance(reply_res, list) and reply_res else reply_res
                return first
            return res


